with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (71, 'Do you like going out with friends?', 'Você gosta de sair com amigos?', '[{"answer":"Yes, I love going out with friends.","translation":"Sim, eu adoro sair com amigos.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially on weekends.","translation":"Sim, especialmente nos fins de semana.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sometimes. I also enjoy staying home.","translation":"Às vezes. Eu também gosto de ficar em casa.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I prefer small gatherings with close friends.","translation":"Eu prefiro encontros pequenos com amigos próximos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Yes, but I don''t go out as often as I used to.","translation":"Sim, mas eu não saio com tanta frequência quanto antes.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (72, 'How often do you see your friends?', 'Com que frequência você vê seus amigos?', '[{"answer":"I see them every week.","translation":"Eu os vejo toda semana.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Usually once or twice a month.","translation":"Geralmente uma ou duas vezes por mês.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I meet my closest friends on weekends.","translation":"Eu encontro meus amigos mais próximos nos fins de semana.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Not very often because we''re all busy.","translation":"Não com muita frequência porque todos estamos ocupados.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It varies, but we try to meet at least once a month.","translation":"Varia, mas tentamos nos encontrar pelo menos uma vez por mês.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (73, 'What do you usually do with your friends?', 'O que você costuma fazer com seus amigos?', '[{"answer":"We usually go out for dinner.","translation":"Nós geralmente saímos para jantar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"We watch movies together.","translation":"Nós assistimos a filmes juntos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"We meet for coffee and talk.","translation":"Nós nos encontramos para tomar café e conversar.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"We sometimes play sports or games.","translation":"Às vezes praticamos esportes ou jogamos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"We usually choose something simple, like having dinner and catching up.","translation":"Nós geralmente escolhemos algo simples, como jantar e colocar a conversa em dia.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (74, 'What qualities do you value in a friend?', 'Que qualidades você valoriza em um amigo ou amiga?', '[{"answer":"I value honesty.","translation":"Eu valorizo a honestidade.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Kindness is very important to me.","translation":"Gentileza é muito importante para mim.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like friends who are reliable.","translation":"Eu gosto de amigos em quem posso confiar.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I value a good sense of humor and respect.","translation":"Eu valorizo bom humor e respeito.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"For me, a good friend is honest, supportive, and easy to talk to.","translation":"Para mim, um bom amigo é honesto, oferece apoio e é fácil de conversar.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (75, 'Are you a shy person?', 'Você é uma pessoa tímida?', '[{"answer":"Yes, I''m a little shy.","translation":"Sim, eu sou um pouco tímido/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Not really. I''m quite outgoing.","translation":"Na verdade, não. Eu sou bastante extrovertido/a.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m shy around new people.","translation":"Eu sou tímido/a perto de pessoas novas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"It depends on the situation.","translation":"Depende da situação.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I used to be very shy, but I''m more confident now.","translation":"Eu costumava ser muito tímido/a, mas agora sou mais confiante.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (76, 'Are you an organized person?', 'Você é uma pessoa organizada?', '[{"answer":"Yes, I''m very organized.","translation":"Sim, eu sou muito organizado/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I try to be organized.","translation":"Eu tento ser organizado/a.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Not always, but I use a calendar.","translation":"Nem sempre, mas eu uso uma agenda.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m organized at work but less organized at home.","translation":"Eu sou organizado/a no trabalho, mas menos em casa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like making lists and planning my week in advance.","translation":"Eu gosto de fazer listas e planejar minha semana com antecedência.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (77, 'Are you usually calm or energetic?', 'Você costuma ser uma pessoa calma ou cheia de energia?', '[{"answer":"I''m usually calm.","translation":"Eu geralmente sou calmo/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m quite energetic.","translation":"Eu sou bastante cheio/a de energia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m calm most of the time.","translation":"Eu sou calmo/a na maior parte do tempo.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"It depends on the day.","translation":"Depende do dia.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m calm at work, but more energetic when I''m with friends.","translation":"Eu sou calmo/a no trabalho, mas mais animado/a quando estou com amigos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (78, 'Do you like meeting new people?', 'Você gosta de conhecer pessoas novas?', '[{"answer":"Yes, I enjoy meeting new people.","translation":"Sim, eu gosto de conhecer pessoas novas.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially when I travel.","translation":"Sim, especialmente quando viajo.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sometimes, although I''m a little shy at first.","translation":"Às vezes, embora eu seja um pouco tímido/a no início.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Not very much. I prefer small groups.","translation":"Não muito. Eu prefiro grupos pequenos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Yes, but I usually need some time to feel comfortable.","translation":"Sim, mas geralmente preciso de algum tempo para me sentir à vontade.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (79, 'Do you prefer talking or listening?', 'Você prefere falar ou ouvir?', '[{"answer":"I prefer listening.","translation":"Eu prefiro ouvir.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I like talking more.","translation":"Eu gosto mais de falar.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I enjoy both.","translation":"Eu gosto dos dois.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I usually listen first and then share my opinion.","translation":"Eu geralmente ouço primeiro e depois compartilho minha opinião.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends on the conversation, but I''m generally a good listener.","translation":"Depende da conversa, mas no geral sou um bom ouvinte/uma boa ouvinte.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (80, 'What makes you happy?', 'O que deixa você feliz?', '[{"answer":"Spending time with my family makes me happy.","translation":"Passar tempo com minha família me deixa feliz.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Good music makes me happy.","translation":"Boa música me deixa feliz.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I feel happy when I''m with friends.","translation":"Eu fico feliz quando estou com amigos.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Learning something new makes me happy.","translation":"Aprender algo novo me deixa feliz.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Simple things like a quiet morning and a good conversation make me happy.","translation":"Coisas simples, como uma manhã tranquila e uma boa conversa, me deixam feliz.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text,question_translation=content.question_translation,answer_examples=content.answer_examples
from card_content content where question.display_order=content.display_order;
